         ) {
        soloPDF['documento_docx'] = archivo;
      }

    }
    item.binary = soloPDF; 
  }
}

return $input.all();

// Obtener los datos de la rama que llegó (solo una tendrá datos)
const inputData = $input.all();

// Si no llegó nada, no hacer nada
if (inputData.length === 0) {
    return [];
}

// Tomar el primer item que llegó (será el PDF, ya sea directo o convertido)
const pdfData = inputData[0];

// Devolver el objeto manteniendo json y binary
return [{
    json: pdfData.json,     // Metadatos del PDF
    binary: pdfData.binary  // Datos binarios del archivo PDF
}];

const items = $input.all();
const resultado = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const binaryData = item.binary;

  if (!binaryData) continue;

  // Buscamos el PDF de forma inteligente (por mimeType o por extensión .pdf)
  const pdfKey = Object.keys(binaryData).find(key => {
    const mime = binaryData[key].mimeType ? binaryData[key].mimeType.toLowerCase() : '';
    const name = binaryData[key].fileName ? binaryData[key].fileName.toLowerCase() : '';
    return mime.includes('pdf') || name.endsWith('.pdf');
  });

  if (pdfKey) {
    // Aislamos SOLO el PDF y descartamos las firmas de correo (logos)
    const soloPDF = {
      'documento_pdf': binaryData[pdfKey]
    };

    resultado.push({
      json: {
        pdf_filename: binaryData[pdfKey].fileName,
        ...item.json
      },
      binary: soloPDF // Enviamos el objeto binario limpio
    });
  }
}

if (resultado.length === 0) {
  for (let i = 0; i < items.length; i++) {
    const item = items[i];
    const binaryData = item.binary;

    if (!binaryData) continue;

    // Buscamos el DOCX de forma inteligente (por mimeType o por extensión .docx)
    const docxKey = Object.keys(binaryData).find(key => {
      const mime = binaryData[key].mimeType ? binaryData[key].mimeType.toLowerCase() : '';
      const name = binaryData[key].fileName ? binaryData[key].fileName.toLowerCase() : '';
      return mime.includes('docx') || name.endsWith('.docx') || mime.includes('doc') || name.endsWith('.doc');
    });

    if (docxKey) {
      // Aislamos SOLO el DOCX y descartamos las firmas de correo (logos)
      const soloPDF = {
        'documento_docx': binaryData[docxKey]
      };

      resultado.push({
        json: {
          docx_filename: binaryData[docxKey].fileName,
          ...item.json
        },
        binary: soloPDF // Enviamos el objeto binario limpio
      });
    }
  }
}

if (resultado.length === 0) {
  resultado.push({
      json: {
        pdf_filename: "",
        docx_filename: "",
      },
    });
  return resultado;
  throw new Error('No se encontró ningún adjunto PDF en los correos recibidos. Verifica que el nodo de Outlook tiene activada la opción "Download Attachments".');
}

return resultado;

const items = $input.all();
// Nodo Code para procesamiento más robusto
const body = items[0].json.body.content || '';
const targetWords = ['pedido', 'compra', 'solicitud'];

// Verifica todas las propiedades disponibles
console.log('Propiedades del item:', Object.keys(items[0].json));
console.log('Contenido completo:', JSON.stringify(items[0].json, null, 2));

// Normalizar texto para mejor detección
const cleanText = body
  .toLowerCase()
  .replace(/[^\w\s]/g, ' ') // Elimina puntuación
  .replace(/\s+/g, ' ');    // Normaliza espacios

// Detectar palabras clave como tokens completos
const tokens = cleanText.split(' ');
const matches = tokens.filter(token => targetWords.includes(token));

// Detectar también frases con "pedido" en contexto
const hasOrderContext = /(realizar|hacer|enviar|confirmar)\s+un?\s+pedido/i.test(body);

// Devolver cuerpo completo y resultado de detección
items[0].json.bodyContent = body;        // Cuerpo completo original
items[0].json.bodyLength = body.length;  // (opcional) longitud del mensaje
items[0].json.hasPedido = matches.length > 0 || hasOrderContext;// Resultado de la búsqueda
items[0].json.matches = matches;

return items;

